func pieces(_ transfers: [Transfer]) -> ([String], [Int]) {
    let posted = transfers.filter { $0.posted }
    let recipients = posted.map { $0.recipient }
    let amounts = posted.compactMap { Int($0.amountText) }
    return (recipients, amounts)
}

filter выбирает записи, map сохраняет по одной подписи на запись, compactMap убирает nil после Int(text). Пока это только технические части, не безопасный денежный отчёт.

