func totalAmount(_ transfers: [Transfer]) -> Int? {
    let posted = transfers.filter { $0.posted }
    let amounts = posted.compactMap { Int($0.amountText) }
    guard amounts.count == posted.count else { return nil }
    return amounts.reduce(0, +)
}

Разница количеств показывает, что compactMap потерял запись. Возвращаем nil вместо правдоподобной неправильной суммы.

